# ruff: noqa: E501  (user-facing guide texts are long prose)
"""Trello through an API key + token generated by the user."""

from __future__ import annotations

import re
from datetime import datetime
from typing import Any, Dict, List

from openjarvis.integrations.base import (
    Field,
    I,
    Integration,
    IntegrationError,
    S,
    register,
    request,
    tool,
)

API = "https://api.trello.com/1"
AUTH_ERROR = (
    "Trello no acepta la clave o el token. Revisa que has copiado los dos "
    "completos (el token es el código largo que aparece tras pulsar «Permitir»)."
)
_ID = re.compile(r"^[0-9a-fA-F]{24}$")


def _fecha(value: str | None) -> str:
    if not value:
        return ""
    try:
        from openjarvis.personal.reminders import local_tz

        dt = datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(local_tz())
        return dt.strftime("%d/%m/%Y %H:%M")
    except Exception:
        return value[:16]


def _auth(creds: Dict[str, str]) -> Dict[str, str]:
    return {"key": creds["key"].strip(), "token": creds["token"].strip()}


def _check(creds: Dict[str, str]) -> str:
    me = request(
        "GET",
        f"{API}/members/me",
        params={**_auth(creds), "fields": "fullName,username"},
        auth_error=AUTH_ERROR,
    )
    return (me or {}).get("fullName") or (me or {}).get("username") or "Trello"


def _tools(creds: Dict[str, str]):
    auth = _auth(creds)

    def call(method: str, path: str, **params: Any) -> Any:
        params = {k: v for k, v in params.items() if v not in (None, "")}
        return request(
            method, f"{API}{path}", params={**auth, **params}, auth_error=AUTH_ERROR
        )

    def boards() -> List[Dict[str, Any]]:
        return (
            call("GET", "/members/me/boards", filter="open", fields="name,shortUrl")
            or []
        )

    def board_id(value: str) -> str:
        value = (value or "").strip()
        if _ID.match(value):
            return value
        for b in boards():
            if b.get("name", "").lower() == value.lower() or b.get("id") == value:
                return b["id"]
        raise IntegrationError(
            f"No encuentro el tablero «{value}». Usa trello_list_boards para ver los nombres."
        )

    @tool(
        "trello_list_boards",
        "Lista los tableros abiertos de Trello del usuario.",
        integration="trello",
    )
    def trello_list_boards() -> Any:
        items = boards()
        if not items:
            return "No tienes tableros abiertos en Trello."
        return [
            {"id": b["id"], "nombre": b.get("name", ""), "url": b.get("shortUrl", "")}
            for b in items
        ]

    @tool(
        "trello_board",
        "Muestra las listas de un tablero de Trello con sus tarjetas (IDs incluidos, "
        "para crear o mover tarjetas).",
        {
            "tablero": S("Nombre o ID del tablero"),
            "max_tarjetas": I("Máximo de tarjetas por lista (por defecto 20)"),
        },
        ["tablero"],
        integration="trello",
    )
    def trello_board(tablero: str, max_tarjetas: int = 20) -> Any:
        per_list = max(1, min(int(max_tarjetas or 20), 100))
        lists = call(
            "GET",
            f"/boards/{board_id(tablero)}/lists",
            cards="open",
            card_fields="name,due,dueComplete,desc",
            filter="open",
            fields="name",
        )
        if not lists:
            return "El tablero no tiene listas."
        out = []
        for lst in lists:
            cards = []
            for c in (lst.get("cards") or [])[:per_list]:
                card: Dict[str, Any] = {"id": c["id"], "nombre": c.get("name", "")}
                if c.get("due"):
                    card["vence"] = _fecha(c["due"]) + (
                        " (hecha)" if c.get("dueComplete") else ""
                    )
                if c.get("desc"):
                    card["descripcion"] = c["desc"][:150]
                cards.append(card)
            out.append(
                {"lista": lst.get("name", ""), "id": lst["id"], "tarjetas": cards}
            )
        return out

    @tool(
        "trello_create_card",
        "Crea una tarjeta en una lista de Trello.",
        {
            "lista_id": S("ID de la lista (de trello_board)"),
            "nombre": S("Título de la tarjeta"),
            "descripcion": S("Descripción (opcional)"),
            "vence": S("Fecha de vencimiento AAAA-MM-DD o AAAA-MM-DDTHH:MM (opcional)"),
        },
        ["lista_id", "nombre"],
        writes=True,
        integration="trello",
    )
    def trello_create_card(
        lista_id: str, nombre: str, descripcion: str = "", vence: str = ""
    ) -> str:
        card = call(
            "POST", "/cards", idList=lista_id, name=nombre, desc=descripcion, due=vence
        )
        return f"Tarjeta creada: «{nombre}» {(card or {}).get('shortUrl', '')}".strip()

    @tool(
        "trello_move_card",
        "Mueve una tarjeta de Trello a otra lista (p. ej. de «Pendiente» a «Hecho»).",
        {
            "tarjeta_id": S("ID de la tarjeta"),
            "lista_id": S("ID de la lista de destino"),
        },
        ["tarjeta_id", "lista_id"],
        writes=True,
        integration="trello",
    )
    def trello_move_card(tarjeta_id: str, lista_id: str) -> str:
        card = call("PUT", f"/cards/{tarjeta_id}", idList=lista_id)
        return f"Tarjeta «{(card or {}).get('name', tarjeta_id)}» movida."

    @tool(
        "trello_comment",
        "Añade un comentario a una tarjeta de Trello.",
        {"tarjeta_id": S("ID de la tarjeta"), "texto": S("Comentario")},
        ["tarjeta_id", "texto"],
        writes=True,
        integration="trello",
    )
    def trello_comment(tarjeta_id: str, texto: str) -> str:
        call("POST", f"/cards/{tarjeta_id}/actions/comments", text=texto)
        return "Comentario añadido."

    return [
        trello_list_boards,
        trello_board,
        trello_create_card,
        trello_move_card,
        trello_comment,
    ]


register(
    Integration(
        id="trello",
        name="Trello",
        category="productividad",
        description="Consulta tus tableros y crea o mueve tarjetas de Trello.",
        abilities=[
            "¿Qué tengo pendiente en el tablero de la reforma?",
            "Crea una tarjeta «Llamar al fontanero» en Pendiente",
            "Mueve la tarjeta del presupuesto a Hecho",
        ],
        steps=[
            'Entra en <a href="https://trello.com/apps/admin" target="_blank" rel="noopener">trello.com/apps/admin</a> (inicia sesión con tu cuenta de Trello) y pulsa «<b>New</b>» (arriba a la derecha).',
            "Rellena el formulario: nombre «Jarvis», elige tu espacio de trabajo, pon tu email en los campos de correo y tu nombre como autor. Si te pregunta por «Power-Up» o «Iframe connector URL», déjalo desmarcado/vacío. Pulsa «<b>Create</b>».",
            "Se abre la página de tu app: ve a la pestaña «<b>Trello Auth</b>» (o «API key») y pulsa «<b>Generate a new API key</b>». Copia la «<b>API key</b>» y pégala aquí abajo.",
            "Al lado de la clave verás un enlace que pone «<b>Token</b>»: púlsalo, revisa la pantalla y pulsa «<b>Allow</b>» (Permitir).",
            "Te aparecerá un código largo: es tu <b>token</b>. Cópialo y pégalo aquí abajo. ¡Hecho!",
        ],
        fields=[
            Field("key", "API key", kind="text", placeholder="32 letras y números"),
            Field("token", "Token", placeholder="ATTA…"),
        ],
        check=_check,
        build_tools=_tools,
        prompt="Herramientas trello_*: listar tableros, ver listas y tarjetas, crear y mover tarjetas, comentar.",
        icon="T",
        color="#0079BF",
        link="https://trello.com",
    )
)
